VERSIONS = ["v1", "v1.1", "v2"]


def transform_v1_to_v1_1(payload):
    result = dict(payload)
    result.setdefault("metadata", {})
    result.setdefault("created_at", None)
    result["v1_1_applied"] = True
    return result


def transform_v1_1_to_v2(payload):
    result = dict(payload)
    result["schema_version"] = "v2"
    result["v2_applied"] = True
    return result


TRANSFORMS = {
    ("v1", "v1.1"): transform_v1_to_v1_1,
    ("v1.1", "v2"): transform_v1_1_to_v2,
}


def coerce_numeric_ids(payload):
    # BUG: only coerces a few top-level keys and ignores nested values.
    result = dict(payload)
    for key in ("event_id", "user_id"):
        if key in result and isinstance(result[key], str) and result[key].isdigit():
            result[key] = int(result[key])
    return result


def migrate_payload(payload, from_version="v1", to_version="v2"):
    # BUG: accesses optional fields directly and skips intermediate transforms.
    result = dict(payload)
    result["metadata"] = payload["metadata"]
    result["created_at"] = payload["created_at"]
    result["schema_version"] = to_version
    return coerce_numeric_ids(result)

