import unittest

from migrator import coerce_numeric_ids, migrate_payload


class TestMigrator(unittest.TestCase):
    def test_missing_optional_fields_do_not_raise(self):
        payload = {"event_id": "1", "type": "created"}
        result = migrate_payload(payload)

        self.assertEqual(result["metadata"], {})
        self.assertIsNone(result["created_at"])
        self.assertEqual(result["schema_version"], "v2")
        self.assertTrue(result["v1_1_applied"])
        self.assertTrue(result["v2_applied"])

    def test_nested_numeric_ids_are_coerced(self):
        payload = {
            "event_id": "123",
            "data": {
                "user_id": "456",
                "items": [{"id": "789"}, {"id": "not-a-number"}],
            },
        }
        result = coerce_numeric_ids(payload)

        self.assertEqual(result["event_id"], 123)
        self.assertEqual(result["data"]["user_id"], 456)
        self.assertEqual(result["data"]["items"][0]["id"], 789)
        self.assertEqual(result["data"]["items"][1]["id"], "not-a-number")

    def test_migration_applies_intermediate_transforms(self):
        payload = {"event_id": "9", "metadata": {"source": "legacy"}}
        result = migrate_payload(payload)

        self.assertEqual(result["event_id"], 9)
        self.assertEqual(result["metadata"], {"source": "legacy"})
        self.assertTrue(result["v1_1_applied"])
        self.assertTrue(result["v2_applied"])
        self.assertEqual(result["schema_version"], "v2")


if __name__ == "__main__":
    unittest.main()
